using System;
using System.Collections.Generic;
using GrimDynasty.ReverseClient.Actions;

// Explicit OWN storage for the observed global setter, never a native startup
// default. Real fixed Lua chunks run; no arbitrary script or fake logger exists.
public static class GameLuaGlueCompletionTests {
 static int scenarios,assertions,olderAssertions;
 static readonly List<object> checks=new List<object>(),receipts=new List<object>();
 static void Check(bool value,string why){assertions++;if(!value)throw new Exception(why);}
 static void Eq<T>(T expected,T actual,string why){Check(EqualityComparer<T>.Default.Equals(expected,actual),why+" expected="+expected+" actual="+actual);}
 static void Same(object expected,object actual,string why){Check(Object.ReferenceEquals(expected,actual),why);}
 static void Missing(uint at,Action action,string why){try{action();}catch(MissingContract error){Eq(at,error.Address,why);return;}throw new Exception("Expected Unsupported: "+why);}
 static void Test(string name,Action action){int before=assertions;action();scenarios++;checks.Add(new Dictionary<string,object>{{"name",name},{"assertions",assertions-before}});}
 static Dictionary<string,object> Call(OwnLuaCallbackResult r){return new Dictionary<string,object>{{"bridge_status",r.BridgeStatus},{"lua_status",r.LuaStatus},{"stage_rva",r.StageRva},{"published_mask",r.PublishedMask},{"callback_calls",r.CallbackCalls},{"logger_calls",r.LoggerCalls},{"resolver_calls",r.ResolverCalls},{"entry_top",r.EntryTop},{"exit_top",r.ExitTop},{"last_measured_local_top",r.FailureLocalTop},{"host_status",r.HostStatus},{"flags",r.Flags},{"fixture_id",r.FixtureId},{"context_token",r.ContextToken},{"host_failure",r.HostFailure},{"host_failure_rva",r.HostFailureRva},{"engine_read_rva",r.EngineReadRva}};}
 static void Remember(OwnLuaGlueCompletionResult r){
  var records=new List<object>();for(int n=0;n<r.Glue.Records.Length;n++){var v=r.Glue.Records[n];records.Add(new Dictionary<string,object>{{"index",n},{"prepared",v.Prepared},{"prepared_length",v.PreparedLength},{"snapshot_offset",v.SnapshotOffset},{"snapshot_bytes",v.SnapshotBytes},{"prepared_sha256",v.PreparedSha256},{"load_status",v.LoadStatus},{"pcall_status",v.PCallStatus},{"published",v.Published},{"table_field_type",v.TableFieldType},{"global_type",v.GlobalType},{"global_alias_equal",v.GlobalAliasEqual}});}
  receipts.Add(new Dictionary<string,object>{{"completion",new Dictionary<string,object>{{"call",Call(r.Call)},{"phase",r.Phase},{"native_return_byte",r.Glue.NativeReturnByte},{"prepared_count",r.Glue.PreparedCount},{"loaded_count",r.Glue.LoadedCount},{"executed_count",r.Glue.ExecutedCount},{"published_count",r.Glue.PublishedCount},{"snapshot_bytes",r.Glue.SnapshotBytes},{"version_publication_mask",r.Glue.VersionPublicationMask},{"records",records},{"registry_published_mask",r.RegistryPublishedMask},{"registry_observed_mask",r.RegistryObservedMask},{"registry_types",r.RegistryTypes},{"luaglue_alias",r.LuaGlueAlias},{"gc_closure_match_mask",r.GcClosureMatchMask},{"flags_known",r.FlagsKnown},{"flags_dword",r.FlagsDword},{"log_returned",r.LogReturned},{"cleanup_current_record",r.CleanupCurrentRecord},{"records_constructed",r.RecordsConstructed},{"records_live_at_flag",r.RecordsLiveAtFlag},{"normal_cleanup_entered",r.NormalCleanupEntered},{"normal_records_completed",r.NormalRecordsCompleted},{"normal_free_attempts",r.NormalFreeAttempts},{"normal_free_successes",r.NormalFreeSuccesses},{"own_free_attempts",r.OwnFreeAttempts},{"own_free_successes",r.OwnFreeSuccesses},{"live_record_allocations",r.LiveRecordAllocations},{"cleanup_trace_count",r.CleanupTraceCount},{"cleanup_trace",r.CleanupTrace},{"prepared_failure_releases",r.PreparedFailureReleases}}}});
 }
 sealed class Scope:IDisposable {
  internal readonly OwnLuaJit204Runtime Runtime=OwnLuaJit204Runtime.OpenOwnProfile();
  internal readonly WorldEngine World=new WorldEngine();
  internal readonly Field<WorldEngine> EngineGlobal=new Field<WorldEngine>();
  internal readonly GameReachedGoalLuaService Service;
  internal readonly OwnLuaCallbackContext Context;
  internal readonly Field<uint> Flags;
  readonly List<OwnLuaJit204State> owned=new List<OwnLuaJit204State>();
  internal OwnLuaCallbackBinding Binding;
  internal Scope(Field<uint> shared){Flags=shared;EngineGlobal.Write(World);Service=GameLuaServiceInitializationContracts.PublishOwnColdService(World,new Invocation());Context=new OwnLuaCallbackContext(Service,EngineGlobal,null);Runtime.SelectOwnRegistry(Context);}
  internal OwnLuaJit204State Current{get{return Service.Lua00.Read(0) as OwnLuaJit204State;}}
  internal void Capture(){var state=Current;if(state!=null&&!owned.Contains(state))owned.Add(state);}
  internal void SetLogging(byte enabled){var i=new Invocation();GameLuaServiceInitializationContracts.SetLuaGlueLogging0743C0(Flags,enabled,i);Eq(0x0743c7u,i.At,"Actual modeled DWORD writer address");Eq(enabled==0?0u:7u,Flags.Read(0),"Observed NEG/SBB/AND7 setter semantics");}
  internal void Callbacks(){var i=new GameLuaCallbackInitializationInvocation();try{Missing(0x0f2ed2,delegate{GameLuaServiceInitializationContracts.InitializeCallbackPrefix0F2E00(Service,GameLuaLibraryBindings.ResolveOwn(Runtime),Runtime,Context,i);},"Real callback prerequisite retains its boundary");}finally{Binding=i.Binding;Capture();}Check(i.Publication!=null&&i.Publication.BridgeStatus==0&&i.Publication.PublishedMask==127,"Actual callbacks published before completion fixture");}
  internal GameLuaGlueCompletionInitializationInvocation FullService(uint stop){var i=new GameLuaGlueCompletionInitializationInvocation();try{Missing(stop,delegate{GameLuaServiceInitializationContracts.InitializeLuaGlueCompletionPrefix0F2E00(Service,GameLuaLibraryBindings.ResolveOwn(Runtime),Runtime,Context,Flags,i);},"Full service entry reaches exact supported boundary");}finally{Binding=i.Binding;Capture();}Check(i.Completion!=null,"Actual completion receipt retained");Remember(i.Completion);Eq(stop,i.Native.At,"Invocation exact stop retained");return i;}
  internal OwnLuaGlueCompletionResult FullBinding(){var r=Binding.InitializeLuaGlueCompletion(Flags);Remember(r);Same(r,Binding.LastLuaGlueCompletionResult,"Actual result belongs to same binding");return r;}
  internal void Fixture(int id){var r=Binding.ExecuteFixture((OwnLuaCallbackFixture)id);receipts.Add(new Dictionary<string,object>{{"fault_setup",Call(r)}});Check(r.FixtureId==(uint)id&&r.BridgeStatus==0&&r.LuaStatus==0,"Fixed OWN environment fault setup actually executed");Check(r.CallbackCalls==0&&r.LoggerCalls==0,"Fault setup does not substitute a logger or execute recovered callbacks");}
  internal void CloseCurrent(){Current.Dispose();Check(!Current.IsAlive&&Binding.IsClosed&&Binding.CloseResult!=null,"Real state close returned and released its binding");receipts.Add(new Dictionary<string,object>{{"close",Call(Binding.CloseResult)}});Eq(-1,Binding.CloseResult.LuaStatus,"Close internal Lua status remains unobserved");Check((Binding.CloseResult.Flags&16)!=0,"Actual close return was observed");}
  public void Dispose(){for(int n=owned.Count-1;n>=0;n--)owned[n].Dispose();Runtime.Dispose();Check(Runtime.ActiveStateCount==0&&Runtime.CloseFailure==null,"Every created state was really closed");Check(Runtime.ModuleUnloadObserved,"OWN runtime modules unload after state cleanup");}
 }
 static void Defined(OwnLuaGlueCompletionResult r){Check(r.Glue.PreparedCount==11&&r.Glue.LoadedCount==11&&r.Glue.ExecutedCount==11&&r.Glue.PublishedCount==4,"Eleven actual definition calls and four flagged aliases completed");Eq(4153u,r.Glue.SnapshotBytes,"Actual prepared prefix retains the known fixed source size");Eq(15u,r.Glue.VersionPublicationMask,"Actual version/table publications returned");Eq(11u,r.RecordsConstructed,"Same eleven OWN records constructed");}
 static void Registry(OwnLuaGlueCompletionResult r){Check(r.RegistryPublishedMask==15&&r.RegistryObservedMask==15&&r.GcClosureMatchMask==3,"Actual four registry writes and closure identity observations completed");Eq(1,r.LuaGlueAlias,"Registry retains the actual __luaglue table identity");Eq(4,r.RegistryTypes.Length,"Four registry type observations");foreach(int type in r.RegistryTypes)Eq(5,type,"Observed registry value is a table");}
 static void NoRegistry(OwnLuaGlueCompletionResult r){Check(r.RegistryPublishedMask==0&&r.RegistryObservedMask==0&&r.GcClosureMatchMask==0,"No later registry operation fabricated");Eq(-1,r.LuaGlueAlias,"Unobserved registry alias remains unknown");foreach(int type in r.RegistryTypes)Eq(-1,type,"Unobserved registry type remains unknown");}
 static void NormalCleanup(OwnLuaGlueCompletionResult r){
  Eq(1u,r.NormalCleanupEntered,"Actual normal cleanup iterator entered");Eq(11u,r.NormalRecordsCompleted,"All same eleven records completed normal destruction");Check(r.NormalFreeAttempts==33&&r.NormalFreeSuccesses==33,"Thirty-three actual normal record releases completed");Check(r.OwnFreeAttempts==0&&r.OwnFreeSuccesses==0,"OWN fallback cleanup did not masquerade as normal releases");Eq(0u,r.LiveRecordAllocations,"No record allocation remains live");Eq(0,r.CleanupCurrentRecord,"Last normal record was zero");Eq(33u,r.CleanupTraceCount,"Actual normal release trace is complete");Eq(33,r.CleanupTrace.Length,"Only observed release entries are exposed");for(int n=0;n<33;n++)Eq((uint)((10-n/3)*3+n%3),r.CleanupTrace[n],"Actual record10-to0 source/chunk/name release order");
 }
 static void OwnCleanup(OwnLuaGlueCompletionResult r,uint records){Eq(records,r.RecordsConstructed,"Actual constructor prefix");Check(r.NormalCleanupEntered==0&&r.NormalRecordsCompleted==0&&r.NormalFreeAttempts==0&&r.NormalFreeSuccesses==0,"Unsupported/unprotected error did not claim original normal destructors");Check(r.OwnFreeAttempts==records*3&&r.OwnFreeSuccesses==records*3&&r.LiveRecordAllocations==0,"OWN error cleanup accounts only for actually constructed record allocations");Check(r.CleanupTraceCount==0&&r.CleanupTrace.Length==0,"No invented original cleanup trace");Eq(-1,r.Glue.NativeReturnByte,"OWN cleanup does not fabricate a native return");}
 static void NoLog(OwnLuaGlueCompletionResult r){Eq(-1,r.LogReturned,"Unexecuted logging return remains unknown");Check(r.Call.CallbackCalls==0&&r.Call.LoggerCalls==0&&r.Call.EngineReadRva==0,"No fake print or Engine logger execution");}
 public static Dictionary<string,object> Run(){
  scenarios=assertions=olderAssertions=0;checks.Clear();receipts.Clear();
  Test("Explicit setter clear branch completes same records across two real VM lifetimes",delegate{
   var shared=new Field<uint>();using(var s=new Scope(shared)){
    Missing(0,delegate{shared.Read(0);},"Global state is unknown before a modeled setter call");s.SetLogging(0);ulong prior=0;
    for(int pass=0;pass<2;pass++){
     if(pass==1)s.Service.Initialized58.Forget();var i=s.FullService(0x0f2eda);var r=i.Completion;Defined(r);Registry(r);NormalCleanup(r);NoLog(r);Check(r.Call.BridgeStatus==0&&r.Call.LuaStatus==0&&(r.Call.Flags&35)==0,"Actual complete helper returned normally without error transfer");Eq(6u,r.Phase,"Native return observed only after normal cleanup");Eq(0x25779au,r.Call.StageRva,"Actual zero-extended native return point");Eq(1,r.Glue.NativeReturnByte,"Clear branch returns actual one");Check(r.FlagsKnown==1&&r.FlagsDword==0&&r.RecordsLiveAtFlag==11,"Live setter-backed global was read while same records remained owned");Eq(0u,r.PreparedFailureReleases,"Normal definitions did not take failed-pcall prepared free");Same(shared,s.Flags,"Same global cell is borrowed");Same(s.Service,s.Binding.Context.Service,"Same service identity retained");Same(s.Current.CallbackBinding,s.Binding,"Same real VM owns this binding");Same(s.Service,GameReachedGoalLogEngine.ForWorldEngine(s.World).LuaService68.Read(0),"Same Engine service publication");Eq(s.Binding.Token,r.Call.ContextToken,"Completion stayed with captured VM context");Check(r.Call.ContextToken!=prior,"Second real VM does not reuse prior context identity");prior=r.Call.ContextToken;if(pass==0)Eq((byte)0,s.Service.Initialized58.Read(0),"Partial service never sets readiness");else Missing(0,delegate{s.Service.Initialized58.Read(0);},"Unknown readiness stays unknown after helper success");s.CloseCurrent();Eq(0u,shared.Read(0),"Closing a VM does not own or rewrite shared global state");
    }
    Eq(2L,s.Runtime.NativeNewStateCalls,"Two real VM lifetimes exercised the same explicit global cell");Eq(2L,s.Runtime.NativeCloseCalls,"Both real VM lifetimes closed");Same(null,s.Context.OwnSink,"No logger adapter installed");
   }
  });
  Test("Unknown live DWORD stops after real definitions and registry with distinct OWN cleanup",delegate{
   using(var s=new Scope(new Field<uint>())){
    var r=s.FullService(0x257707).Completion;Defined(r);Registry(r);OwnCleanup(r,11);NoLog(r);Eq(3u,r.Phase,"Unknown flag stops in feature read phase");Eq(0,r.FlagsKnown,"Actual live flag read was unknown");Eq(11,r.RecordsLiveAtFlag,"All actual records survived until the flag read");Check(r.Call.BridgeStatus==7&&r.Call.LuaStatus>0&&(r.Call.Flags&3)==3&&(r.Call.Flags&32)==0,"Unknown flag uses OWN protection without claiming normal-zero return");Eq(0x257707u,r.Call.HostFailureRva,"Typed global read failure retains exact address");Missing(0,delegate{s.Flags.Read(0);},"No zero flag fallback written");Eq((byte)0,s.Service.Initialized58.Read(0),"Unknown flag leaves readiness unchanged");
   }
