    s.SetLogging(1);var r=s.FullService(0x257724).Completion;Defined(r);Registry(r);OwnCleanup(r,11);NoLog(r);Eq(4u,r.Phase,"Set-bit path stops at log boundary");Check(r.FlagsKnown==1&&r.FlagsDword==7&&r.RecordsLiveAtFlag==11,"True setter produces actual DWORD7 and tests bit zero");Eq(7u,r.Call.BridgeStatus,"Log dependency remains Unsupported");Eq(0x257724u,r.Call.StageRva,"No claim that formatting or logger was called");Check((r.Call.Flags&32)==0,"Log stop is not a handled pcall return-zero path");Eq(7u,s.Flags.Read(0),"Boundary does not change shared flag");Eq((byte)0,s.Service.Initialized58.Read(0),"Log boundary cannot initialize service");
