    s.Callbacks();s.Fixture(21);var r=s.FullBinding();NormalCleanup(r);NoRegistry(r);NoLog(r);Eq(6u,r.Phase,"Normal failure tail really reached return");Eq(0,r.Glue.NativeReturnByte,"Actual failed-pcall branch returns zero");Eq(0x25779au,r.Call.StageRva,"Handled failure completed the same return point");Check(r.Call.BridgeStatus==6&&r.Call.LuaStatus>0&&(r.Call.Flags&35)==35,"OWN rethrow transports actual error only after normal-zero completion");Check(r.Call.ExitTop==r.Call.EntryTop+1&&s.Current.GetTop(0)==r.Call.ExitTop,"Actual error object survives outside the OWN protected frame");Check(r.Glue.PreparedCount==1&&r.Glue.LoadedCount==1&&r.Glue.ExecutedCount==0&&r.Glue.PublishedCount==0,"First actual chunk loaded but its definition assignment failed");Check(r.Glue.Records[0].LoadStatus==0&&r.Glue.Records[0].PCallStatus>0,"Real load and inner pcall statuses remain distinct");Eq(15u,r.Glue.VersionPublicationMask,"Actual earlier version publications remain");Eq(11u,r.RecordsConstructed,"All original record constructions precede first execution");Eq(1u,r.PreparedFailureReleases,"Observed257774 prepared-buffer free actually occurred");Check(r.FlagsKnown==-1&&r.RecordsLiveAtFlag==-1,"Failed pcall never reached feature-state read");Missing(0,delegate{s.Flags.Read(0);},"Unconsumed global remains unknown");Eq((byte)0,s.Service.Initialized58.Read(0),"Native helper zero return does not set readiness");s.CloseCurrent();
