    if(id==22){Check(r.Glue.VersionPublicationMask==15&&r.Glue.PreparedCount==1&&r.Glue.LoadedCount==1&&r.Glue.ExecutedCount==0&&r.Glue.PublishedCount==0,"Real first chunk failed inside the production callback");Check(r.Glue.Records[0].LoadStatus==0&&r.Glue.Records[0].PCallStatus>0,"Unknown callback caused a real inner pcall error");Check(r.Call.CallbackCalls==1&&r.Call.LoggerCalls==1&&r.Call.HostStatus==1,"Actual production print reached unknown host logger");Eq(0x0f2d00u,r.Call.EngineReadRva,"Real print leaf consumed shared Engine");Eq(0x0f2d12u,r.Call.HostFailureRva,"Unknown Engine logger vtable remains exact Unsupported");Eq(-1,r.LogReturned,"Feature-tail logging helper never ran");Same(null,s.Context.OwnSink,"No synthetic sink turned unknown logger into success");}
